package com.bananalab.lite;
import android.content.Context;import org.json.*;import java.util.*;import java.util.regex.*;import java.io.*;
/** Exact, explainable local edit planner. Unsupported clauses abort the whole batch. */
final class AppJavaChat{
 static final String HELP="Puedo cambiar tres módulos Java y definir una función de salto. Para crear una curva nueva: ‘como cambio la funcion del salto’.\n\nAjustes de módulos:\n• Agranda el texto del chat.\n• Agranda los botones de la app.\n• Pone el tema de la app violeta.\n• Crea una pantalla de proyectos.\n• Aumenta la altura de los saltos.\n• Hace los gestos mas suaves.\n• Usa seis pares de mensajes como contexto.\n\nVarios cambios: ‘prepara estos cambios: agranda el texto del chat; aumenta la altura de los saltos’. Compilo una copia; después podés aplicar o descartar.\n‘Versiones de la app’, ‘mostrame el mapa del codigo’ y ‘deshace el ultimo cambio de la app’. Celebración y beso conservan sus pedidos anteriores.\n\nSon módulos preparados, no un programador Java general. El chat también puede generar métodos acotados y reconstruir clases compatibles en una APK normal. Los permisos, bibliotecas y funciones arbitrarias siguen fuera del alcance.";
 static final class Plan{AppJavaWorkspace.Settings settings;String summary="";boolean handled,preview;}
 static int number(String q,int fallback){Matcher m=Pattern.compile("\\b([0-9]+)\\b").matcher(q);if(m.find())return Integer.parseInt(m.group(1));String[] words={"cero","uno","dos","tres","cuatro","cinco","seis","siete","ocho"};for(int i=1;i<words.length;i++)if(q.matches("(?s).*\\b"+words[i]+"\\b.*"))return i;return fallback;}
 static String edit(String q,AppJavaWorkspace.Settings s){
  Matcher face=Pattern.compile("pone la fuente de la app (original|sans serif|serif|monospace|sans serif medium)").matcher(q);if(face.matches()){s.font=Arrays.asList("original","sans serif","serif","monospace","sans serif medium").indexOf(face.group(1));return "Fuente de la interfaz: "+face.group(1)+".";}
  Matcher single=Pattern.compile("pone el boton ([a-z0-9 ]+?) (original|azul|verde|violeta|rojo|amarillo)").matcher(q);if(single.matches()){try{s.buttonColors.put(single.group(1),Arrays.asList("original","azul","verde","violeta","rojo","amarillo").indexOf(single.group(2)));}catch(Exception e){throw new IllegalArgumentException(e);}return "Color del botón «"+single.group(1)+"»: "+single.group(2)+". Se aplica a ese nombre cuando está visible.";}
  Matcher color=Pattern.compile("pone los botones de la app (original|azul|verde|violeta|rojo|amarillo)").matcher(q);if(color.matches()){s.accent=Arrays.asList("original","azul","verde","violeta","rojo","amarillo").indexOf(color.group(1));return "Color de botones: "+color.group(1)+".";}
  Matcher m=Pattern.compile("(?:pone|cambia) el (?:tamano del )?texto del chat (?:a|en) ([0-9]+)").matcher(q);if(m.matches()){s.text=Integer.parseInt(m.group(1));return "Texto del chat: "+s.text+" sp.";}
  if(q.matches("(?:agranda|aumenta|achica|reduce) (?:la letra|el texto) del chat")){s.text+=q.startsWith("agranda")||q.startsWith("aumenta")?2:-2;return "Texto del chat: "+s.text+" sp.";}
  if(q.matches("(?:agranda|achica) los botones de la app")){s.buttons+=q.startsWith("agranda")?2:-2;return "Botones: "+s.buttons+" sp.";}
  if(q.matches("(?:aumenta|reduce) el espacio entre mensajes")){s.spacing+=q.startsWith("aumenta")?2:-2;return "Espacio entre mensajes: "+s.spacing+" dp.";}
  m=Pattern.compile("(?:pone|cambia) el tema de la app (?:a )?(oscuro|azul|verde|violeta)").matcher(q);if(m.matches()){s.theme=Arrays.asList("oscuro","azul","verde","violeta").indexOf(m.group(1));return "Tema de la app: "+m.group(1)+".";}
  if(q.matches("crea una pantalla de proyectos|agrega una pantalla de proyectos|activa la pantalla de proyectos|quita la pantalla de proyectos")){s.projects=!q.startsWith("quita");return s.projects?"Pantalla de proyectos disponible desde el encabezado y el chat.":"Oculté el acceso a la pantalla de proyectos; los proyectos se conservan.";}
  if(q.matches("(?:aumenta|reduce) la altura de los saltos|hace que todos los personajes salten mas (?:alto|bajo)")){s.jump=Math.round((s.jump+(q.startsWith("reduce")||q.endsWith("bajo")?-.25f:.25f))*100)/100f;return "Altura global de saltos: ×"+s.jump+".";}
  if(q.matches("hace los gestos mas (?:suaves|amplios)|(?:reduce|aumenta) la amplitud de los gestos")){s.gesture=Math.round((s.gesture+(q.endsWith("suaves")||q.startsWith("reduce")?-.2f:.2f))*100)/100f;return "Amplitud de gestos: ×"+s.gesture+".";}
  if(q.matches("usa (?:[0-9]+|uno|dos|tres|cuatro|cinco|seis|siete|ocho) pares de mensajes como contexto")){s.context=number(q,3);return "Contexto: hasta "+s.context+" pares recientes; la capacidad del modelo sigue limitada.";}
  return null;
 }
 static Plan plan(String input,AppJavaWorkspace.Settings current)throws Exception{Plan p=new Plan();p.settings=current.copy();String raw=input.trim();p.preview=ChatLanguage.normalize(raw).startsWith("prepara estos cambios");boolean batch=p.preview||ChatLanguage.normalize(raw).startsWith("cambia estas partes de la app");if(batch){int colon=raw.indexOf(':');p.handled=true;if(colon<0)throw new IllegalArgumentException("Escribí los cambios después de dos puntos y separalos con punto y coma. No cambié nada.");raw=raw.substring(colon+1);}
  String[] clauses=raw.split(";",-1);if(clauses.length>8)throw new IllegalArgumentException("Podés agrupar hasta ocho ajustes por vez.");List<String> summary=new ArrayList<>();for(String clause:clauses){String q=ChatLanguage.normalize(clause);String item=edit(q,p.settings);if(item==null){if(batch||p.handled)throw new IllegalArgumentException("No puedo aplicar esta parte: ‘"+clause.trim()+"’. Conservé todos los módulos. Pedí ‘que podes cambiar de la app’ para ver el alcance.");return p;}p.handled=true;summary.add(item);}AppJavaWorkspace.validate(p.settings);p.summary=JavaCompat.join("\n",summary);return p;}
 static String asset(Context c,String name,int limit)throws Exception{try(InputStream in=c.getAssets().open(name)){return new String(OnDeviceJava.bytes(in,limit),"UTF-8");}}
 static String map(Context c)throws Exception{JSONArray files=new JSONObject(asset(c,"code-map.json",1500000)).getJSONArray("files");return "Mapa del código instalado · "+files.length()+" archivos Java indexados.\nInterfaz: BananaActivity → BananaInterface.\nAnimación: Scene / RigRenderer → BananaAnimation.\nContexto: BananaConversation → BananaDialogue.\nCelebración / beso: JavaLive → BananaBehavior.\nCompilación: OnDeviceJava; versiones: AppJavaWorkspace.\n\n‘Mostrame el codigo de Scene.java’ lee el código de la versión instalada. ‘Mostrame los modulos de la app’ muestra los archivos modificables activos. El índice no convierte los archivos del APK en editables.";}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String q=ChatLanguage.normalize(input);
  if(q.matches("deshace ese ajuste|deshace el ultimo ajuste de la app|volve al funcionamiento anterior")&&AppJavaWorkspace.prefs(c).getLong("changedAt",0)>JavaLive.prefs(c).getLong("changedAt",0))return operation(c,1,null);
  if(q.matches("que podes cambiar de la app|como puedo ajustar la app hablando|quiero mejorar la app|mejora la app|como cambio la app|que podes ajustar hablando"))return MobileCore.say(c,HELP,"app_ajuste");
  if(q.matches("mostrame el mapa del codigo|mapa del codigo|que archivos tiene la app"))return MobileCore.say(c,map(c),"app_ajuste");
  if(q.equals("mostrame los modulos de la app")){String raw=AppJavaWorkspace.prefs(c).getString("active","");AppJavaWorkspace.Settings s=raw.isEmpty()?new AppJavaWorkspace.Settings():AppJavaWorkspace.Settings.read(new JSONObject(raw).getJSONObject("settings"));StringBuilder out=new StringBuilder();for(Map.Entry<String,String> e:AppJavaWorkspace.sources(s).entrySet())out.append(e.getKey()).append("\n").append(e.getValue()).append("\n");return MobileCore.say(c,out.toString(),"app_ajuste");}
  Matcher file=Pattern.compile("(?i)^mostrame el c[oó]digo de ([a-zA-Z][a-zA-Z0-9]*\\.java)[?. ]*$").matcher(input.trim());if(file.matches()){String name=file.group(1);JSONArray files=new JSONObject(asset(c,"code-map.json",1500000)).getJSONArray("files");for(int i=0;i<files.length();i++)if(files.getJSONObject(i).getString("name").equals(name)){String code=asset(c,"app-source/"+name,250000);return MobileCore.say(c,name+" · código instalado, lectura\n"+code.substring(0,Math.min(code.length(),9000))+(code.length()>9000?"\n[Vista abreviada; archivo completo en las fuentes de Banana.]":""),"app_ajuste");}return MobileCore.say(c,"No encontré ese archivo. Pedí el mapa del código para ubicar la parte que querés revisar.","app_ajuste");}
  if(q.matches("mostrame la pantalla de proyectos|abrir proyectos|abri proyectos"))return MobileCore.say(c,AppJavaWorkspace.live.projects?"Abrí la pantalla de proyectos.":"Primero pedí ‘crea una pantalla de proyectos’ para activar este acceso.",AppJavaWorkspace.live.projects?"app_proyectos":"app_ajuste");
  if(q.matches("versiones de la app|historial de cambios de la app"))return MobileCore.say(c,AppJavaWorkspace.versions(c),"app_ajuste");
  if(q.equals("descarta los cambios de la app")){if(!AppJavaWorkspace.prefs(c).edit().remove("draft").commit())throw new IOException("No pude descartar la prueba.");return MobileCore.say(c,"Descarté la prueba. El funcionamiento activo se conserva.","app_ajuste");}
  if(q.equals("ver cambios pendientes de la app")){String raw=AppJavaWorkspace.prefs(c).getString("draft","");return MobileCore.say(c,raw.isEmpty()?"No hay cambios de la app pendientes.":"Prueba compilada, sin activar:\n"+new JSONObject(raw).getString("summary"),"app_ajuste");}
  if(q.equals("aplica los cambios de la app"))return operation(c,0,null);
  if(q.equals("deshace el ultimo cambio de la app"))return operation(c,1,null);
  Matcher recover=Pattern.compile("volve a la version ([0-9]{1,9}) de la app").matcher(q);if(recover.matches())return operation(c,Integer.parseInt(recover.group(1))+2,null);
  if(q.matches("busca como arreglar el error de la app|busca el error de la app")){String error=AppJavaWorkspace.prefs(c).getString("error","");if(error.isEmpty())return MobileCore.say(c,"No hay un error de módulos guardado para investigar.","app_ajuste");return MobileCore.say(c,ResearchConversation.reply(c,"busca documentacion Android Java ECJ DX "+error.replaceAll("/[^ ]+","archivo").substring(0,Math.min(180,error.replaceAll("/[^ ]+","archivo").length())),""),"fuentes");}
  try{Plan p=plan(input,AppJavaWorkspace.live);if(p.handled)return operation(c,-1,p);if(q.matches("(?s)^(?:agranda|achica|aumenta|reduce|pone|cambia|hace|usa|crea|agrega|quita) .*(?:texto del chat|letra del chat|botones de la app|tema de la app|pantalla de proyectos|altura de los saltos|amplitud de los gestos|pares de mensajes como contexto).*"))return MobileCore.say(c,"No entendí el ajuste completo. No cambié la app ni la escena. Separá los ajustes con punto y coma o pedí ‘que podes cambiar de la app’.","app_ajuste");}catch(IllegalArgumentException invalid){return MobileCore.say(c,invalid.getMessage(),"app_ajuste");}
  if(q.matches("(?s)^(?:reescribe toda la app|cambia todo el codigo|reconstrui la app|modifica cualquier java|agrega una funcion nueva a la app).*"))return MobileCore.say(c,"Puedo reconstruir Banana.apk desde el dispositivo para clases compatibles; todavía no genero Java arbitrario. Puedo compilar cambios en los módulos de interfaz, animación y contexto. Pedí ‘que podes cambiar de la app’ para ver las opciones reales.","app_ajuste");
  return null;
 }
 static BananaEngine.Result operation(Context c,int op,Plan p)throws Exception{JavaChat.owner=Thread.currentThread();try{String text;if(op==0)text=AppJavaWorkspace.apply(c);else if(op==1){JSONArray h=AppJavaWorkspace.history(c);text=h.length()==0?"No hay una versión anterior de los módulos de la app.":AppJavaWorkspace.recover(c,h.getJSONObject(h.length()-1).getInt("id"));}else if(op>=2)text=AppJavaWorkspace.recover(c,op-2);else{if(p.settings.json().toString().equals(AppJavaWorkspace.live.json().toString()))return MobileCore.say(c,"Esos módulos ya tienen los valores pedidos. No cambié nada.","app_ajuste");text=AppJavaWorkspace.prepare(c,p.settings,p.summary);if(!p.preview)text=AppJavaWorkspace.apply(c);}return MobileCore.say(c,text,"app_ajuste");}catch(Throwable failure){AppJavaWorkspace.prefs(c).edit().putString("error",failure.toString()).apply();return MobileCore.say(c,"No pude completar el cambio de módulos. La versión activa se conserva. Podés pedir ‘versiones de la app’ o ‘busca el error de la app’.\nDetalle: "+failure.getClass().getSimpleName(),"app_ajuste");}finally{JavaChat.progress="";JavaChat.owner=null;}}
}
